// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 10

// thresholdsPath 是阈值配置文件的路径，按源码位置解析，
// 不依赖进程的工作目录。
var thresholdsPath = defaultThresholdsPath()

func defaultThresholdsPath() string {
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		return filepath.Join("config", "thresholds.json")
	}
	return filepath.Join(filepath.Dir(file), "..", "config", "thresholds.json")
}

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 阈值来自 config/thresholds.json 里该仓库的配置；没配或配置不可用时
// 回退 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	if threshold, ok := loadThresholds()[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取阈值配置。文件不存在、读不出来或内容不是 JSON 对象时
// 返回 nil，由调用方回退默认值。
func loadThresholds() map[string]int {
	data, err := os.ReadFile(thresholdsPath)
	if err != nil {
		return nil
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}

package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// pointThresholdsAt 把阈值来源临时指向 path，测试结束后还原。
func pointThresholdsAt(t *testing.T, path string) {
	t.Helper()
	original := thresholdsPath
	thresholdsPath = path
	t.Cleanup(func() { thresholdsPath = original })
}

func TestConfiguredWarehouseUsesItsThreshold(t *testing.T) {
	if got := LowStockThreshold("shanghai"); got != 20 {
		t.Fatalf("LowStockThreshold(%q) = %d, 期望 20", "shanghai", got)
	}
}

func TestDefaultLowStockThresholdIsTen(t *testing.T) {
	if DefaultLowStockThreshold != 10 {
		t.Fatalf("DefaultLowStockThreshold = %d, 期望 10", DefaultLowStockThreshold)
	}
}

func TestMissingThresholdsFileFallsBackToDefault(t *testing.T) {
	pointThresholdsAt(t, filepath.Join(t.TempDir(), "missing.json"))
	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("文件不存在时应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

func TestUnreadableThresholdsFileFallsBackToDefault(t *testing.T) {
	// 用一个目录冒充配置文件：ReadFile 必然失败。
	path := filepath.Join(t.TempDir(), "thresholds.json")
	if err := os.Mkdir(path, 0o755); err != nil {
		t.Fatal(err)
	}
	pointThresholdsAt(t, path)
	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("文件读不出来时应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

func TestNonObjectThresholdsFileFallsBackToDefault(t *testing.T) {
	for _, content := range []string{"[1,2,3]", `"shanghai"`, "not json"} {
		path := filepath.Join(t.TempDir(), "thresholds.json")
		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
			t.Fatal(err)
		}
		pointThresholdsAt(t, path)
		if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
			t.Fatalf("内容 %q 不是 JSON 对象时应回退默认值 %d，得到 %d",
				content, DefaultLowStockThreshold, got)
		}
	}
}
